const msg = $json;
const binary = $binary ?? {};

const MAILBOX_ID = 'avisarnoam1@gmail.com';

// --------------------------------------------------
// Sender
// --------------------------------------------------

let sender = null;

if (msg.from?.text) {
  sender = msg.from.text;
} else if (msg.from?.value?.length) {
  const firstSender = msg.from.value[0];

  sender = firstSender.name
    ? `${firstSender.name} <${firstSender.address}>`
    : firstSender.address;
}

// --------------------------------------------------
// Subject
// --------------------------------------------------

const subject = msg.subject ?? null;

// --------------------------------------------------
// Received date
// --------------------------------------------------

let receivedAt = null;

if (msg.date) {
  const parsedDate = new Date(msg.date);

  if (!Number.isNaN(parsedDate.getTime())) {
    receivedAt = parsedDate.toISOString();
  }
}

// --------------------------------------------------
// Body
// Prefer text/plain. Fall back to HTML.
// --------------------------------------------------

let textBody = '';

if (typeof msg.text === 'string' && msg.text.trim()) {
  textBody = msg.text.trim();
} else if (typeof msg.html === 'string' && msg.html.trim()) {
  textBody = msg.html
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/\s+\n/g, '\n')
    .replace(/\n\s+/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .trim();
}

// --------------------------------------------------
// Attachments from n8n binary data
// --------------------------------------------------

const attachmentSources = Object.entries(binary).map(
  ([binaryPropertyName, file]) => {

    const attachmentId =
      `${msg.id ?? 'unknown'}:${binaryPropertyName}`;

    return {
      attachment_id: attachmentId,

      // Internal n8n field.
      // This is NOT sent inside EmailEnvelope.
      binary_property: binaryPropertyName,

      filename: file.fileName ?? null,
      mime_type:
        file.mimeType ?? 'application/octet-stream',

      // Debug only.
      file_size: file.fileSize ?? null,
    };
  }
);

// --------------------------------------------------
// EmailEnvelope sent to /triage
// --------------------------------------------------

const emailEnvelope = {
  mailbox_id: MAILBOX_ID,
  message_id: msg.id ?? null,
  thread_id: msg.threadId ?? null,
  received_at: receivedAt,
  sender,
  subject: subject ?? "",
  text_body: textBody ?? "",

  attachments: attachmentSources.map(a => ({
    filename: a.filename,
    mime_type: a.mime_type,
    attachment_id: a.attachment_id,
  })),
};

return {
  json: {
    email_envelope: emailEnvelope,

    // Internal workflow helper.
    // POST /triage does not receive this object.
    attachment_sources: attachmentSources,
  },

// Keep the downloaded attachment alive.
  binary,
};

const triage = $json;

return {
  json: {
    opportunity_id: triage.opportunity_id,
    status: triage.record_status,
    action: triage.action,
    reason:
      triage.classification?.rationale
      ?? triage.error_code
      ?? 'No reason returned',
    reused: triage.reused ?? false,
    host_record_relative_path:
      `data/m2_received/${triage.opportunity_id}/record.json`,
  },
};

const triage = $('POST Classification').item.json;

const envelope =
  $('Normalize Gmail Message').item.json.email_envelope;

const opportunityId =
  triage.opportunity_id
  ?? `m2_${envelope.message_id}`;

const hasAttachmentReason =
  typeof $json.reason === 'string'
  && $json.reason.length > 0;

const outcomeStatus =
  $json.outcome_status
  ?? (hasAttachmentReason ? 'review_manual' : 'failed');

const reason =
  $json.reason
  ?? triage.error_code
  ?? `unexpected_triage_action_${String(triage.action)}`;

return {
  json: {
    opportunity_id: opportunityId,
    outcome_status: outcomeStatus,
    reason: String(reason).slice(0, 1000),
    error_code:
      outcomeStatus === 'failed'
        ? (triage.error_code ?? 'workflow_routing_failed')
        : 'attachment_not_ready',
  },
};

const response = $json;
const result = response.body ?? response;

if (!result.opportunity_id || !result.status) {
  throw new Error('API returned an unexpected analysis response');
}

return {
  json: {
    opportunity_id: result.opportunity_id,
    status: result.status,
    reason: result.reason,
    error_code: result.error_code,
    analyst_runs: result.analyst_runs,
    reused: result.reused,
    report_ready: result.status === 'completed',
    host_record_relative_path:
      `data/m2_received/${result.opportunity_id}/record.json`,
    host_brief_relative_path:
      result.status === 'completed'
        ? `data/m2_received/${result.opportunity_id}/brief.txt`
        : null,
  },
};

// --------------------------------------------------
// Read data already created by previous nodes
// --------------------------------------------------

const normalizedNode =
  $('Normalize Gmail Message').item;

const envelope =
  normalizedNode.json.email_envelope;

const attachmentSources =
  normalizedNode.json.attachment_sources ?? [];

const triageResult =
  $('POST Triage').item.json;

// Get the actual downloaded files from Gmail.
const gmailItem =
  $('Get Full Message').item;

const binary =
  gmailItem.binary ?? {};


// --------------------------------------------------
// Stable opportunity ID
// --------------------------------------------------

// Prefer the ID returned by /triage.
// Keep the old M2 convention only as a fallback.
const opportunityId =
  triageResult.opportunity_id ??
  `m2_${envelope.message_id}`;

const PPTX_MIME =
  'application/vnd.openxmlformats-officedocument.presentationml.presentation';


// --------------------------------------------------
// Find PPTX attachments
// --------------------------------------------------

const pptxFiles =
  attachmentSources.filter(a => {

    const mimeType =
      String(
        a.mime_type ?? ''
      ).toLowerCase();

    const filename =
      String(
        a.filename ?? ''
      ).toLowerCase();

    return (
      mimeType === PPTX_MIME ||
      filename.endsWith('.pptx')
    );
  });


// --------------------------------------------------
// We require EXACTLY ONE PPTX
// --------------------------------------------------

if (pptxFiles.length !== 1) {
  return {
    json: {
      ready: false,

      reason:
        `expected_exactly_one_pptx_found_${pptxFiles.length}`,

      pptx_count:
        pptxFiles.length,

      opportunity_id:
        opportunityId,

      message_id:
        envelope.message_id,

      email:
        envelope,

      binary_properties_found:
        Object.keys(binary),
    }
  };
}


// --------------------------------------------------
// Validate that the corresponding binary exists
// --------------------------------------------------

const pptx =
  pptxFiles[0];

if (
  !pptx.binary_property ||
  !binary[pptx.binary_property]
) {
  return {
    json: {
      ready: false,

      reason:
        'pptx_metadata_found_but_binary_missing',

      pptx_count:
        1,

      opportunity_id:
        opportunityId,

      message_id:
        envelope.message_id,

      email:
        envelope,

      binary_property:
        pptx.binary_property ?? null,

      binary_properties_found:
        Object.keys(binary),
    }
  };
}


// --------------------------------------------------
// Success
// --------------------------------------------------

return {
  json: {
    ready: true,

    pptx_count:
      1,

    opportunity_id:
      opportunityId,

    message_id:
      envelope.message_id,

    email:
      envelope,

    attachment_id:
      pptx.attachment_id,

    filename:
      pptx.filename,

    mime_type:
      pptx.mime_type,

    binary_property:
      pptx.binary_property,
  },

  // Pass the actual PPTX binary to the next node.
  binary,
};

const binaryProperty =
  $json.binary_property;

if (!binaryProperty) {
  throw new Error(
    'binary_property is missing'
  );
}

if (!$binary?.[binaryProperty]) {
  throw new Error(
    `Binary property "${binaryProperty}" is missing`
  );
}


// --------------------------------------------------
// Read actual PPTX bytes from n8n binary storage
// --------------------------------------------------

const buffer =
  await this.helpers.getBinaryDataBuffer(
    0,
    binaryProperty
  );

if (!buffer || buffer.length === 0) {
  throw new Error(
    'PPTX binary buffer is empty'
  );
}


// --------------------------------------------------
// Demo limit: 10 MiB decoded file
// --------------------------------------------------

const MAX_DECK_BYTES =
  10 * 1024 * 1024;

if (buffer.length > MAX_DECK_BYTES) {
  throw new Error(
    `PPTX exceeds 10 MiB demo limit: ${buffer.length} bytes`
  );
}


// --------------------------------------------------
// Convert raw PPTX bytes to Base64
// --------------------------------------------------

const contentBase64 =
  buffer.toString('base64');


// --------------------------------------------------
// Build Analyze request data
// --------------------------------------------------

return {
  json: {
    opportunity_id:
      $json.opportunity_id,

    email:
      $json.email,

    attachment_id:
      $json.attachment_id,

    filename:
      $json.filename,

    mime_type:
      $json.mime_type,

    content_base64:
      contentBase64,

    decoded_size_bytes:
      buffer.length,
  }
};
